$('undoButton').onclick=()=>history(true);$('redoButton').onclick=()=>history(false);$('newButton').onclick=resetMap;$('exampleButton').onclick=loadExample;$('emptyExample').onclick=loadExample;$('saveButton').onclick=saveFile;$('openButton').onclick=()=>$('fileInput').click();$('helpButton').onclick=showGuide;$('referenceButton').onclick=showReference;
$('zoomIn').onclick=()=>zoom(1.2);$('zoomOut').onclick=()=>zoom(1/1.2);$('zoomLabel').onclick=()=>zoom(1/map.view.scale);$('fitButton').onclick=fit;
