if(pointers.size===2){if(gesture?.before&&JSON.stringify(gesture.before)!==JSON.stringify(snapshot()))pushHistory(gesture.before);gesture=null;const [a,b]=[...pointers.values()],cx=(a.x+b.x)/2,cy=(a.y+b.y)/2;pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),scale:map.view.scale,world:point(cx,cy)};canvas.setPointerCapture(e.pointerId);return;}
canvas.focus({preventScroll:true});const target=e.target.closest('[data-node]'),edge=e.target.closest('[data-edge]'),port=e.target.closest('[data-port]'),resize=e.target.closest('[data-resize]');
